1	import { useState, useMemo, useEffect, useRef } from "react";
2	import { Link } from "wouter";
3	import {
4	  ChevronLeft, ChevronRight, ChevronDown,
5	  Check, Timer, Play, Pause, RotateCcw, ArrowLeft,
6	} from "lucide-react";
7	import { useQueryClient } from "@tanstack/react-query";
8	import {
9	  useGetOverdueItems,
10	  useUpdateTask,
11	  useUpdateEblast,
12	  getGetOverdueItemsQueryKey,
13	  getGetDashboardSummaryQueryKey,
14	} from "@workspace/api-client-react";
15	import { Button } from "@/components/ui/button";
16	import { Skeleton } from "@/components/ui/skeleton";
17	import { Textarea } from "@/components/ui/textarea";
18	import { formatDate } from "@/lib/date-utils";
19	
20	const CATEGORY_COLORS: Record<string, string> = {
21	  "Show Bucket":        "bg-blue-500/15 text-blue-400 border-blue-500/30",
22	  "Fire Marshal":       "bg-red-500/15 text-red-400 border-red-500/30",
23	  "ID Sign":            "bg-purple-500/15 text-purple-400 border-purple-500/30",
24	  "Warehouse Manifest": "bg-cyan-500/15 text-cyan-400 border-cyan-500/30",
25	  "Vehicle Spotting":   "bg-amber-500/15 text-amber-400 border-amber-500/30",
26	  eblast:               "bg-pink-500/15 text-pink-400 border-pink-500/30",
27	};
28	
29	function chipClass(type: string, category: string | null | undefined) {
30	  if (type === "eblast") return CATEGORY_COLORS["eblast"];
31	  return CATEGORY_COLORS[category ?? ""] ?? "bg-slate-500/15 text-slate-400 border-slate-500/30";
32	}
33	
34	function itemKey(type: string, id: number) {
35	  return `${type}-${id}`;
36	}
37	
38	function formatTime(secs: number) {
39	  const m = Math.floor(secs / 60).toString().padStart(2, "0");
40	  const s = (secs % 60).toString().padStart(2, "0");
41	  return `${m}:${s}`;
42	}
