        {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
      </span>
      <p className="text-sm font-bold leading-snug truncate">{item.name}</p>
    </div>
    <Link href={`/shows/${item.showId}?tab=${showTab}`} className="shrink-0">
      <Button variant="outline" size="sm">Open</Button>
    </Link>
  </div>

  <p className="text-xs text-muted-foreground">
    {item.showName}
    <span className="mx-1.5 opacity-40">•</span>
    Due {formatDate(item.dueDate)}
  </p>

  {/* Note */}
  {!isNoteOpen ? (
    <button
      onClick={openNote}
      className="flex items-center gap-1.5 w-full text-left text-xs text-muted-foreground hover:text-foreground transition-colors group"
    >
      <ChevronDown className="h-3 w-3 shrink-0 opacity-50 group-hover:opacity-80" />
      <span className="truncate">{currentNote || "Add a note…"}</span>
    </button>
  ) : (
    <div className="flex flex-col gap-1">
      <Textarea
        key={key}
        autoFocus
        value={currentNote}
        onChange={e => setNoteDrafts(p => ({ ...p, [key]: e.target.value }))}
        onBlur={closeNote}
        placeholder="Add a note…"
        className="resize-none text-xs min-h-[52px]"
        rows={2}
      />
      {savedFlash[key] && <span className="text-xs text-muted-foreground">Saved</span>}
    </div>
  )}
</div>

{/* Footer band */}
<div className={`px-4 py-2 flex items-center justify-between gap-3 ${footerBand}`}>

